void AbsoluteControl(const QString&base){scenario="absolute-roots-control";const auto roots=Setup(base);QString error;Check(CloudBackupArchive::RootsCurrent(roots,error),"absolute roots match current effective context");for(const auto&p:Paths(roots))Check(QDir::isAbsolutePath(p)&&QDir::cleanPath(p)==p&&!p.contains(QChar('\0')),"absolute capture remains absolute and normalized");}
void RelativeCapture(const QString&base){scenario="relative-portable-capture-and-cwd-snapshot";CurrentDirectory cwd;const auto absolute=Setup(base+"/anchor");Check(QDir().mkpath(base+"/other-cwd"),"prepare independent second current directory",true);Check(QDir::setCurrent(base+"/anchor"),"set owned portable current directory",true);SetRelative();CloudBackupRoots relative;QString error;const bool captured=CloudBackupArchive::CaptureRoots(relative,error);Check(captured,"relative portable paths capture successfully");observed.append(QJsonObject{{"case",scenario},{"captured",captured},{"error",error}});if(!captured){observed.append(QJsonObject{{"case",scenario},{"remaining_snapshot_checks","not reached because relative capture failed; not counted as accepted"}});return;}
 const auto paths=Paths(relative),expected=Paths(absolute);for(int i=0;i<paths.size();++i){Check(QDir::isAbsolutePath(paths[i])&&QDir::cleanPath(paths[i])==paths[i],"captured root is absolute and normalized: "+QString::number(i));Check(paths[i]==expected[i],"captured root resolves to expected lexical destination: "+QString::number(i));}Check(relative.identity==absolute.identity,"relative and equivalent absolute roots have the same identity");Check(CloudBackupArchive::RootsCurrent(relative,error),"relative capture matches unchanged current context");const auto source=relative.scenesRoot+"/collection.json";Write(source,"{\"scene\":\"captured-A\"}");Check(QDir::setCurrent(base+"/other-cwd"),"change process current directory after snapshot",true);Check(!CloudBackupArchive::RootsCurrent(relative,error)&&!error.isEmpty(),"RootsCurrent rejects relative context retargeted by later cwd");CloudBackupRoots elsewhere;Check(CloudBackupArchive::CaptureRoots(elsewhere,error),"new relative context still captures normalized roots",true);Check(elsewhere.scenesRoot!=relative.scenesRoot,"new capture reflects distinct current-directory context");const auto otherBefore=Tree(base+"/other-cwd");CloudBackupOptions options;options.generalSettings=false;options.profiles=false;options.scenes=true;options.pluginSettings=false;options.preserveLocalDevices=false;QByteArray archive;CloudBackupSummary summary;Check(CloudBackupArchive::Create(relative,options,archive,summary,error),"Create after cwd change uses immutable captured roots",true);Check(summary.fileCount==1,"Create reads one original captured scene");Write(source,"{\"scene\":\"local-edit-after-backup\"}");QString safety;Check(CloudBackupArchive::StageRestore(relative,archive,options,safety,error),"Stage after cwd change uses immutable captured roots",true);Check(CloudBackupArchive::HasPendingRestore(relative),"pending belongs to original captured context");Check(!CloudBackupArchive::HasPendingRestore(elsewhere),"new current-directory context has no pending restore");Check(CloudBackupArchive::ApplyPendingRestore(relative,error),"Apply after cwd change uses original captured snapshot",true);Check(Read(source)=="{\"scene\":\"captured-A\"}","original target restored from captured source");Check(!CloudBackupArchive::HasPendingRestore(relative),"successful original Apply removes pending");Check(Tree(base+"/other-cwd")==otherBefore,"new current-directory target tree remains unchanged");auto*a=App();a->userConfigLocation=filesystem::u8path((base+"/anchor/configuration").toStdString());a->userProfilesLocation=filesystem::u8path((base+"/anchor/profiles").toStdString());a->userScenesLocation=filesystem::u8path((base+"/anchor/scenes").toStdString());a->userPluginManagerSettingsLocation=filesystem::u8path((base+"/anchor/plugins").toStdString());globalConfigBase=filesystem::u8path((base+"/anchor/global").toStdString());Check(CloudBackupArchive::RootsCurrent(relative,error),"equivalent absolute App context matches snapshot despite cwd change");observed.append(QJsonObject{{"case",scenario},{"captured_identity",relative.identity},{"captured_paths",QJsonArray::fromStringList(paths)},{"later_capture_identity",elsewhere.identity},{"source_after",QString::fromUtf8(Read(source))}});}
void EmptyInvalidControls(const QString&base){scenario="empty-invalid-capture-failclosed";const auto valid=Setup(base);const auto saved=*App();QString error;for(int i=0;i<4;++i){*App()=saved;switch(i){case 0:App()->userConfigLocation.clear();break;case 1:App()->userProfilesLocation.clear();break;case 2:App()->userScenesLocation.clear();break;case 3:App()->userPluginManagerSettingsLocation.clear();break;}CloudBackupRoots result=valid;Check(!CloudBackupArchive::CaptureRoots(result,error)&&!error.isEmpty()&&result.identity==valid.identity,"empty base rejected without overwriting caller snapshot: "+QString::number(i));}*App()=saved;App()->userScenesLocation=filesystem::u8path(string("invalid\0path",12));CloudBackupRoots result=valid;Check(!CloudBackupArchive::CaptureRoots(result,error)&&!error.isEmpty()&&result.identity==valid.identity,"embedded NUL rejected without overwriting caller snapshot");*App()=saved;fakeGlobalEmpty=true;Check(!CloudBackupArchive::CaptureRoots(result,error)&&!error.isEmpty()&&result.identity==valid.identity,"empty global path rejected without current-directory fallback");fakeGlobalEmpty=false;fakeAppAvailable=false;Check(!CloudBackupArchive::CaptureRoots(result,error)&&!error.isEmpty(),"unavailable App rejected");fakeAppAvailable=true;*App()=saved;Check(CloudBackupArchive::RootsCurrent(valid,error),"valid absolute context still accepted after invalid controls");}
